import json, os, subprocess, sys
from pathlib import Path
os.environ["HF_HUB_DISABLE_XET"] = "1"
os.environ["HF_HUB_DISABLE_PROGRESS_BARS"] = "1"
os.environ["OMP_NUM_THREADS"] = "2"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", 'scikit-learn==1.8.0', 'pandas==3.0.3', 'joblib==1.5.3', 'huggingface-hub==1.22.0', 'pyarrow>=20', 'pytest'], check=True)
root = Path("/tmp/aimo-e37")
entries = json.loads('{"train/audit_e38_prefix.py": "\\"\\"\\"Audit exact cross-budget prefix identity without reading labels (E38a).\\n\\nRun: python train/audit_e38_prefix.py --out-dir runs/e38-prefix-audit\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport hashlib\\nimport importlib.metadata\\nimport json\\nfrom pathlib import Path\\n\\nimport pandas as pd\\nfrom huggingface_hub import hf_hub_download\\n\\nDATASET = \\"ssubhnil/Qwen3-Math-Eval\\"\\nREVISION = \\"f64c82f5ce9249155ad7c70991a9711d92963cce\\"\\nMODELS = (\\"qwen3-1.7b\\", \\"qwen3-4b\\", \\"qwen3-8b\\", \\"qwen3-14b\\")\\nBUDGETS = (2048, 4096, 8192, 16384)\\nCOLUMNS = [\\"model\\", \\"problem_id\\", \\"variant\\", \\"token_budget\\", \\"trace\\", \\"temperature\\", \\"seed\\", \\"answer_forced\\"]\\n\\n\\ndef audit_cell(frame: pd.DataFrame, anchor: str) -> dict:\\n    rows = frame.loc[frame.variant.eq(anchor) & frame.token_budget.isin(BUDGETS)].copy()\\n    if rows.empty or rows.duplicated([\\"problem_id\\", \\"token_budget\\"]).any():\\n        raise ValueError(\\"empty or duplicate anchor observations\\")\\n    if not rows.temperature.eq(0).all() or not rows.seed.eq(42).all():\\n        raise ValueError(\\"non-frozen sampling settings\\")\\n    if rows.trace.isna().any() or rows.trace.str.len().eq(0).any():\\n        raise ValueError(\\"empty trace\\")\\n    counts = {str(b): {\\"comparisons\\": 0, \\"mismatches\\": 0, \\"forced_comparisons\\": 0,\\n                      \\"forced_mismatches\\": 0, \\"natural_comparisons\\": 0, \\"natural_mismatches\\": 0}\\n              for b in BUDGETS[:-1]}\\n    problems = 0\\n    for _, part in rows.groupby(\\"problem_id\\", sort=True):\\n        if set(part.token_budget) != set(BUDGETS) or len(part) != 4:\\n            raise ValueError(\\"incomplete budget matrix\\")\\n        part = part.set_index(\\"token_budget\\")\\n        longest = part.loc[16384, \\"trace\\"].encode(\\"utf-8\\")\\n        for budget in BUDGETS[:-1]:\\n            shorter = part.loc[budget, \\"trace\\"].encode(\\"utf-8\\")\\n            mismatch = not longest.startswith(shorter)\\n            kind = \\"forced\\" if bool(part.loc[budget, \\"answer_forced\\"]) else \\"natural\\"\\n            c = counts[str(budget)]\\n            c[\\"comparisons\\"] += 1\\n            c[\\"mismatches\\"] += int(mismatch)\\n            c[f\\"{kind}_comparisons\\"] += 1\\n            c[f\\"{kind}_mismatches\\"] += int(mismatch)\\n        problems += 1\\n    return {\\"problems\\": problems, \\"budgets\\": counts,\\n            \\"comparisons\\": sum(c[\\"comparisons\\"] for c in counts.values()),\\n            \\"mismatches\\": sum(c[\\"mismatches\\"] for c in counts.values())}\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--out-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--cache-dir\\", type=Path, default=Path(\\"data/e38-hf-cache\\"))\\n    args = parser.parse_args()\\n    cells, files = {}, []\\n    for source, anchor in ((\\"math_perturb\\", \\"base\\"), (\\"gsm_plus\\", \\"problem understanding\\")):\\n        for model in MODELS:\\n            name = f\\"data/{source}/{model}.parquet\\"\\n            path = Path(hf_hub_download(DATASET, name, repo_type=\\"dataset\\", revision=REVISION,\\n                                       cache_dir=args.cache_dir, token=False))\\n            with path.open(\\"rb\\") as handle:\\n                digest = hashlib.file_digest(handle, \\"sha256\\").hexdigest()\\n            frame = pd.read_parquet(path, columns=COLUMNS)\\n            if set(frame.model) != {model}:\\n                raise ValueError(f\\"unexpected model in {name}\\")\\n            result = audit_cell(frame, anchor)\\n            cells[f\\"{source}/{model}\\"] = result\\n            files.append({\\"path\\": name, \\"sha256\\": digest, \\"bytes\\": path.stat().st_size})\\n            print(f\\"{source}/{model}: {result[\'mismatches\']}/{result[\'comparisons\']} mismatches\\", flush=True)\\n    gates = {\\"at_least_50_problems_per_cell\\": all(c[\\"problems\\"] >= 50 for c in cells.values()),\\n             \\"exact_prefixes_everywhere\\": all(c[\\"mismatches\\"] == 0 for c in cells.values())}\\n    result = {\\"stage\\": \\"E38a exact-prefix audit\\", \\"dataset\\": DATASET, \\"revision\\": REVISION,\\n              \\"columns_read\\": COLUMNS, \\"cells\\": cells, \\"files\\": files,\\n              \\"comparisons\\": sum(c[\\"comparisons\\"] for c in cells.values()),\\n              \\"mismatches\\": sum(c[\\"mismatches\\"] for c in cells.values()),\\n              \\"gates\\": gates, \\"passed\\": all(gates.values()),\\n              \\"packages\\": {p: importlib.metadata.version(p) for p in (\\"pandas\\", \\"pyarrow\\", \\"huggingface-hub\\")}}\\n    args.out_dir.mkdir(parents=True, exist_ok=True)\\n    (args.out_dir / \\"result.json\\").write_text(json.dumps(result, indent=2) + \\"\\\\n\\")\\n    print(json.dumps({\\"gates\\": gates, \\"passed\\": result[\\"passed\\"]}), flush=True)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "train/test_audit_e38_prefix.py": "import pandas as pd\\nimport pytest\\nfrom audit_e38_prefix import audit_cell\\n\\n\\ndef frame():\\n    return pd.DataFrame([{\\"problem_id\\": \\"p\\", \\"variant\\": \\"base\\", \\"token_budget\\": budget,\\n                          \\"trace\\": trace, \\"temperature\\": 0, \\"seed\\": 42, \\"answer_forced\\": i < 3}\\n                         for i, (budget, trace) in enumerate(zip((2048, 4096, 8192, 16384),\\n                                                                (\\"a\\", \\"ab\\", \\"abc\\", \\"abcd\\")))])\\n\\n\\ndef test_exact_prefixes_and_a_real_divergence():\\n    data = frame()\\n    assert audit_cell(data, \\"base\\")[\\"mismatches\\"] == 0\\n    data.loc[1, \\"trace\\"] = \\"a b\\"  # Whitespace differences must not be hidden.\\n    result = audit_cell(data, \\"base\\")\\n    assert result[\\"mismatches\\"] == 1\\n    assert result[\\"budgets\\"][\\"4096\\"][\\"forced_mismatches\\"] == 1\\n\\n\\ndef test_missing_and_duplicate_budgets_rejected():\\n    data = frame()\\n    with pytest.raises(ValueError, match=\\"incomplete\\"):\\n        audit_cell(data.iloc[:-1], \\"base\\")\\n    with pytest.raises(ValueError, match=\\"duplicate\\"):\\n        audit_cell(pd.concat([data, data.iloc[:1]]), \\"base\\")\\n\\n\\ndef test_non_deterministic_settings_rejected():\\n    data = frame()\\n    data.loc[0, \\"temperature\\"] = 1\\n    with pytest.raises(ValueError, match=\\"sampling\\"):\\n        audit_cell(data, \\"base\\")\\n", "protocols/E38_PROTOCOL.md": "# E38: exact-prefix audit for cheaper budget-path inference\\n\\nStatus: frozen before inspecting cross-budget trace equality. This is an execution-cost\\nexperiment, not a new robustness predictor or another test of E37\'s labels.\\n\\n## Question\\n\\nCan one longest greedy trace supply the shorter-budget primary traces exactly? If so,\\nwe may avoid repeated decoding while keeping E37\'s four budgets and feature definitions.\\nForced-answer calls would still run separately at each budget. Temperature zero alone\\ndoes not establish equivalence: batch scheduling and numerical differences can alter tokens.\\n\\n## E38a: archive screening (CPU, run first)\\n\\n- Dataset: `ssubhnil/Qwen3-Math-Eval`, revision\\n  `f64c82f5ce9249155ad7c70991a9711d92963cce`.\\n- Use all four Qwen3 model shards in `math_perturb` and `gsm_plus`.\\n- Select only `base` (MATH) or `problem understanding` (GSM) rows at budgets\\n  2048, 4096, 8192 and 16384. Do not read correctness, answers, question text, or labels.\\n- Require exactly one row per source/model/problem/budget, nonempty traces, temperature\\n  zero and seed 42. Each model/source cell must have at least 50 complete problems.\\n- For each shorter budget compare its raw stored trace with the start of the 16384-token\\n  trace, byte for byte after UTF-8 encoding. Do not strip whitespace, alter text, or filter\\n  on forced-answer status. Report counts by model, source, budget and forced status.\\n- Gate: **zero mismatches in every cell**. Any mismatch closes archive-based trace reuse;\\n  preserve E37\'s independent budget generations. No near-match tolerance or selective reuse.\\n- Store hashes and counts, not traces, in the tracked result. This audit does not compute\\n  or reuse an accuracy metric. Neither success nor failure changes E37\'s scientific gates.\\n\\n## E38b: target-engine equivalence (conditional draft)\\n\\nOnly if E38a passes, run a GPU equivalence test on the four actual Small-track models,\\nusing the first six distinct official problem keys in sorted order, without inspecting\\ntheir robustness labels. Freeze the exact implementation and record model revisions first.\\nCompare independent-budget token IDs, all forced answers, all 18 features, and final scores\\nagainst a longest-trace implementation. Require exact token/answer equality, feature equality\\nto 1e-12, identical decisions, and at least 20% lower warm generation runtime on each model.\\nFailed equality rejects the optimization; do not change budgets, precision, rank fractions,\\nfeatures or coefficients to rescue it. Cap the conditional pilot at one 2-T4 session per\\nmodel and reassess capacity before launching. E38b never overrides E37\'s existing runtime gate.\\n\\nNo E38 Codabench upload is authorized by the CPU audit alone.\\n"}')
for name, text in entries.items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
subprocess.run([sys.executable, "-m", "pytest", "-q", *['train/test_audit_e38_prefix.py']], cwd=root, check=True)
subprocess.run([sys.executable, 'train/audit_e38_prefix.py', "--cache-dir", "/tmp/e37-hf", "--out-dir", "/kaggle/working/e38"], cwd=root, check=True)
